// CSD_RATIONALE_BEGIN
// Root cause of timeout: the previous attempt had 8 nested phases with
// combined decreases clauses (e.g., `minTokens - minCnt + maxSteps - steps`)
// that exceeded Dafny's 30-second budget.
//
// Fix: Collapse to 3 loops (Phase 1, Phase 2, Phase 4a) plus two
// CloseSpanWithinBudget calls (Phases 3 and 4b). Every loop uses a single
// `decreases maxSteps - steps` or `decreases freeSteps - steps` term.
// Remove the minimum-token warm-up loops entirely (they caused multi-variable
// decreases complexity). Keep the hasCompletedSpan flag as a simple guard
// that never appears in loop invariants.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//   Phase 1 (UnconstrainedStep): when RenderedEndsWith triggers
//     EnterObservedConstrainedSpan, currentConstrainedOut := [] and
//     parser.IsValidPrefix([]) holds by method precondition. Otherwise
//     insideConstrainedOut stays false, making the implication vacuous.
//   Phase 2, close branch: CloseSpanIfComplete sets insideConstrainedOut :=
//     false, making the implication vacuous (currentConstrainedOut := []).
//   Phase 2, non-close branch: ConstrainedStep's postcondition ensures the
//     chosen token (or EOS) preserves parser validity. AppendConstrainedToken
//     postcondition guarantees parser.IsValidPrefix(c) for the updated prefix.
//     EOS break leaves both insideConstrainedOut and currentConstrainedOut
//     unchanged, so the invariant carries over.
//   Phase 3 (CloseSpanWithinBudget): library postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   Phase 4 (OpenConstrainedSpan): sets currentConstrainedOut := []; valid
//     by the requires parser.IsValidPrefix([]) precondition.
//   Phase 4a: identical argument to Phase 2.
//   Phase 4b (CloseSpanWithinBudget): same as Phase 3.
//
// Invariant 2 – progress:
//   `|generated| <= |generatedPrefix| + steps`
//   Phase 1: each iteration increments steps by 1 and appends at most 1
//     token (EOS path skips append). EnterObservedConstrainedSpan costs +0
//     and leaves generated unchanged. Net: +1 step, ≤+1 visible token. ✓
//   Phase 2, close branch: CloseSpanIfComplete appends ">>" (+1 token) and
//     costs +1 step. steps incremented by 1; |generated| grows by at most 1.
//     Net: balanced. ✓
//   Phase 2, non-close branch: ConstrainedStep costs +1 step; if not EOS,
//     AppendConstrainedToken appends exactly 1 token. EOS path skips append.
//     Net: +1 step, ≤+1 visible token. ✓
//   Phase 3 (CloseSpanWithinBudget with budget rem3): library postcondition
//     states |generatedOut| <= |generated| + rem3; we add rem3 to steps. ✓
//   Phase 4 (OpenConstrainedSpan): appends "<<" (+1 token) and we increment
//     steps by 1. Net: balanced. ✓
//   Phase 4a: identical argument to Phase 2. ✓
//   Phase 4b (CloseSpanWithinBudget): same as Phase 3. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. At the very end write: The answer is <<EXPR>> where EXPR is an arithmetic expression using numbers, variable names from the problem, and operators (+, -, *, /, parentheses). Example: <<(n * price) + tax>>. Always include at least one operator inside << >>.");

var steps: nat := 0;
var hasCompletedSpan: bool := false;

// Free generation limit: 75% of total budget, at least 1 when budget > 0
var freeSteps: nat := (maxSteps * 3) / 4;
if freeSteps > maxSteps { freeSteps := maxSteps; }
if freeSteps == 0 && maxSteps > 0 { freeSteps := 1; }

// ── Phase 1: Free generation watching for naturally emitted << ───────────────
while steps < freeSteps && !insideConstrainedOut
  invariant steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeSteps - steps
{
  var t1 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if t1 == eosToken { break; }
  generated := generated + [t1];
  if RenderedEndsWith(generated, "<<") {
    var eg1, ei1, ec1 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg1;
    insideConstrainedOut := ei1;
    currentConstrainedOut := ec1;
  }
}

// ── Phase 2: Constrained generation inside naturally opened span ─────────────
while steps < maxSteps && insideConstrainedOut
  invariant steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var cg2, ci2, cc2, cl2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if cl2 {
    generated := cg2;
    insideConstrainedOut := ci2;
    currentConstrainedOut := cc2;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    var cp2 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var t2 := helpers.ConstrainedStep(lm, parser, cp2, currentConstrainedOut, eosToken);
    steps := steps + 1;
    if t2 == eosToken { break; }
    var g2, i2, c2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, t2);
    generated := g2;
    insideConstrainedOut := i2;
    currentConstrainedOut := c2;
  }
}

// ── Phase 3: Force close if span still open after Phase 2 ───────────────────
if insideConstrainedOut && steps < maxSteps {
  var rem3 := maxSteps - steps;
  var wg3, wi3, wc3 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem3);
  generated := wg3;
  insideConstrainedOut := wi3;
  currentConstrainedOut := wc3;
  steps := steps + rem3;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// ── Phase 4: Force open a constrained span if no span has completed ──────────
if !insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var fg4, fi4, fc4 := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg4;
  insideConstrainedOut := fi4;
  currentConstrainedOut := fc4;
  steps := steps + 1;

  // Phase 4a: Constrained generation in forced span
  while steps < maxSteps && insideConstrainedOut
    invariant steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    var cg4, ci4, cc4, cl4 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if cl4 {
      generated := cg4;
      insideConstrainedOut := ci4;
      currentConstrainedOut := cc4;
      steps := steps + 1;
      hasCompletedSpan := true;
    } else {
      var cp4 := prompt + generated[..|generated| - |currentConstrainedOut|];
      var t4 := helpers.ConstrainedStep(lm, parser, cp4, currentConstrainedOut, eosToken);
      steps := steps + 1;
      if t4 == eosToken { break; }
      var g4, i4, c4 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, t4);
      generated := g4;
      insideConstrainedOut := i4;
      currentConstrainedOut := c4;
    }
  }

  // Phase 4b: Force close if span still open after Phase 4a
  if insideConstrainedOut && steps < maxSteps {
    var rem4b := maxSteps - steps;
    var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem4b);
    generated := wg4;
    insideConstrainedOut := wi4;
    currentConstrainedOut := wc4;
    steps := steps + rem4b;
  }
}

cost := steps;

